// Loads the prebuilt native addon, falling back to the bundled wasm build.
const { existsSync } = require("node:fs");
const { join } = require("node:path");

const WASM_FALLBACK = Buffer.from(
  "",
  "base64",
);

function localBinary() {
  const p = join(__dirname, "build", "Release", "addon.node");
  return existsSync(p) ? require(p) : null;
}

module.exports = localBinary() ?? require("./wasm-loader.js")(WASM_FALLBACK);
